import unittest
import flags


class TestParseBool(unittest.TestCase):
    def test_true_values(self):
        for text in ("true", "yes", "on", "1"):
            self.assertIs(flags.parse_bool(text), True)

    def test_false_values(self):
        for text in ("false", "no", "off", "0"):
            self.assertIs(flags.parse_bool(text), False)

    def test_case_insensitivity(self):
        for text in ("TRUE", "True", "tRuE", "YES", "Yes", "ON", "On"):
            self.assertIs(flags.parse_bool(text), True)
        for text in ("FALSE", "False", "fAlSe", "NO", "No", "OFF", "Off"):
            self.assertIs(flags.parse_bool(text), False)

    def test_ignoring_surrounding_whitespace(self):
        for text in ("  true  ", "\tyes\n", "  on ", " 1 \t", " TRUE \n"):
            self.assertIs(flags.parse_bool(text), True)
        for text in ("  false  ", "\tno\n", "  off ", " 0 \t", " FALSE \n"):
            self.assertIs(flags.parse_bool(text), False)

    def test_empty_string_raises_value_error(self):
        with self.assertRaises(ValueError):
            flags.parse_bool("")

    def test_whitespace_only_raises_value_error(self):
        for text in (" ", "   ", "\t", "\n", " \t\n "):
            with self.assertRaises(ValueError):
                flags.parse_bool(text)

    def test_invalid_values_raise_value_error(self):
        invalid_inputs = (
            "2",
            "-1",
            "maybe",
            "null",
            "none",
            "undefined",
            "t",
            "f",
            "y",
            "n",
            "true1",
            "false0",
            "not",
            "offset",
            "yesterday",
            "true false",
        )
        for text in invalid_inputs:
            with self.assertRaises(ValueError):
                flags.parse_bool(text)


if __name__ == "__main__":
    unittest.main()

