import unittest
import ranges


class TestParseRange(unittest.TestCase):
    def test_single_number(self):
        self.assertEqual(ranges.parse_range("0"), [0])
        self.assertEqual(ranges.parse_range("5"), [5])
        self.assertEqual(ranges.parse_range("42"), [42])

    def test_inclusive_range(self):
        self.assertEqual(ranges.parse_range("0-3"), [0, 1, 2, 3])
        self.assertEqual(ranges.parse_range("2-6"), [2, 3, 4, 5, 6])

    def test_range_equal_endpoints(self):
        self.assertEqual(ranges.parse_range("0-0"), [0])
        self.assertEqual(ranges.parse_range("4-4"), [4])

    def test_invalid_a_exceeds_b(self):
        with self.assertRaises(ValueError):
            ranges.parse_range("5-4")
        with self.assertRaises(ValueError):
            ranges.parse_range("1-0")

    def test_invalid_negative_numbers(self):
        with self.assertRaises(ValueError):
            ranges.parse_range("-1")
        with self.assertRaises(ValueError):
            ranges.parse_range("-3-5")
        with self.assertRaises(ValueError):
            ranges.parse_range("1--5")

    def test_invalid_whitespace(self):
        for text in (" 1", "1 ", " 1-3", "1-3 ", "1 - 3", "1 -3", "1- 3"):
            with self.assertRaises(ValueError):
                ranges.parse_range(text)

    def test_invalid_non_ascii_digits(self):
        for text in ("\u0661", "\u0661-\u0663", "\uff11-\uff13"):
            with self.assertRaises(ValueError):
                ranges.parse_range(text)

    def test_invalid_other_characters(self):
        for text in ("a", "1-b", "x-y", "1.5", "1-2.5", "1,2", "1:3"):
            with self.assertRaises(ValueError):
                ranges.parse_range(text)

    def test_invalid_format(self):
        for text in ("", "-", "1-", "-1", "1-2-3"):
            with self.assertRaises(ValueError):
                ranges.parse_range(text)


if __name__ == "__main__":
    unittest.main()

